class Solution {
    public String addBinary(String a, String b) {
        StringBuilder reversed = new StringBuilder();
        int i = a.length() - 1;
        int j = b.length() - 1;
        int carry = 0;

        while (i >= 0 || j >= 0 || carry > 0) {
            int sum = carry;
            if (i >= 0) {
                sum += a.charAt(i--) - '0';
            }
            if (j >= 0) {
                sum += b.charAt(j--) - '0';
            }
            reversed.append((char) ('0' + (sum & 1)));
            carry = sum >> 1;
        }

        return reversed.reverse().toString();
    }
}

class Solution {
    public String addBinary(String a, String b) {
        int i = a.length() - 1;
        int j = b.length() - 1;
        int carry = 0;
        char[] buffer = new char[Math.max(a.length(), b.length()) + 1];
        int write = buffer.length - 1;

        while (i >= 0 || j >= 0 || carry > 0) {
            int sum = carry;
            if (i >= 0) {
                sum += a.charAt(i--) - '0';
            }
            if (j >= 0) {
                sum += b.charAt(j--) - '0';
            }
            buffer[write--] = (char) ('0' + (sum % 2));
            carry = sum / 2;
        }

        return new String(buffer, write + 1, buffer.length - write - 1);
    }
}

import java.util.ArrayDeque;

class Solution {
    public String addBinary(String a, String b) {
        ArrayDeque<Character> digits = new ArrayDeque<>();
        int i = a.length() - 1;
        int j = b.length() - 1;
        int carry = 0;

        while (i >= 0 || j >= 0 || carry != 0) {
            int sum = carry;
            if (i >= 0) {
                sum += a.charAt(i--) - '0';
            }
            if (j >= 0) {
                sum += b.charAt(j--) - '0';
            }
            digits.addFirst((char) ('0' + (sum & 1)));
            carry = sum >> 1;
        }

        StringBuilder answer = new StringBuilder(digits.size());
        while (!digits.isEmpty()) {
            answer.append(digits.removeFirst());
        }
        return answer.toString();
    }
}

class Solution {
    private static final char[] OUT_BIT = {'0', '1', '1', '0', '1', '0', '0', '1'};
    private static final int[] NEXT_CARRY = {0, 0, 0, 1, 0, 1, 1, 1};

    public String addBinary(String a, String b) {
        StringBuilder reversed = new StringBuilder();
        int i = a.length() - 1;
        int j = b.length() - 1;
        int carry = 0;

        while (i >= 0 || j >= 0 || carry != 0) {
            int bitA = i >= 0 ? a.charAt(i--) - '0' : 0;
            int bitB = j >= 0 ? b.charAt(j--) - '0' : 0;
            int state = (bitA << 2) | (bitB << 1) | carry;
            reversed.append(OUT_BIT[state]);
            carry = NEXT_CARRY[state];
        }

        return reversed.reverse().toString();
    }
}

import java.util.ArrayDeque;

class Solution {
    public String addBinary(String a, String b) {
        ArrayDeque<Integer> first = new ArrayDeque<>();
        ArrayDeque<Integer> second = new ArrayDeque<>();
        for (int i = 0; i < a.length(); i++) {
            first.push(a.charAt(i) - '0');
        }
        for (int i = 0; i < b.length(); i++) {
            second.push(b.charAt(i) - '0');
        }

        StringBuilder reversed = new StringBuilder();
        int carry = 0;
        while (!first.isEmpty() || !second.isEmpty() || carry != 0) {
            int sum = carry;
            if (!first.isEmpty()) {
                sum += first.pop();
            }
            if (!second.isEmpty()) {
                sum += second.pop();
            }
            reversed.append((char) ('0' + (sum % 2)));
            carry = sum / 2;
        }
        return reversed.reverse().toString();
    }
}
